/*
 *  som_lexer.c
 *
 *  The Synth-O-Matic lexical analyzer, from the original lexer.c.  It reads
 *  the program text of the current context instead of a TextEdit handle.
 */

#include <ctype.h>
#include "som_internal.h"

#include "som_grammar.h"	/* token numbers, generated by bison */

#define text	(som_cur->x_text)
#define textlen	(som_cur->x_textlen)
#define textpos	(som_cur->x_textpos)

static int autodeclare = 1;

static int processident(char *token);
static int processconst(char *token);

void
initlexer(void) {
	textlen = (int)strlen(text);
	textpos = 0;
	varlevel = 0;
	funclevel = 0;
	constlevel = 0;
	numconsts = 0;
	lineno = 0;
	yylen = 0;
}

static int
input(void) {
	int c;
	if (textpos >= textlen) {
		c = EOF;
	} else {
		c = (unsigned char)text[textpos++];
	}
	if (c == EOF) return 0;
	if (c == '\n' || c == '\r') {
		lineno++;
	}
	if (yylen < (int)sizeof(yytext) - 1) yytext[yylen++] = c;
	return c;
}

static void
unput(int c) {
	if (textpos>0) textpos--;
	if (yylen > 0) --yylen;
	if (c == '\n' || c == '\r') lineno--;
}

int
yylex(void *lvalp) {
	int r, c;
	memcpy(som_cur->x_prevtext, yytext, sizeof(yytext));
	yylen = 0;

start:
	c = input();

	if (isspace(c)) {
		yylen = 0;
		goto start;
	}
	else if (c == '@') goto fileident;
	else if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_') goto ident;
	else if (c >= '0' && c <= '9') goto digits_1;
	else if (c == '/') {
		c = input();
		if (c == '/') goto comment1;
		else if (c == '*') goto comment2;
		else if (c == '=') {
			r = DIVEQ;
			goto leave;
		} else {
			unput(c);
			r = '/';
			goto leave;
		}
	}
	else if (c == '.') goto digpoint_2;
	else if (c == '+') {
		c = input();
		if (c == '=') {
			r = PLUSEQ;
			goto leave;
		} else {
			unput(c);
			r = '+';
			goto leave;
		}
	}
	else if (c == '-') {
		c = input();
		if (c == '=') {
			r = MINUSEQ;
			goto leave;
		} else {
			unput(c);
			r = '-';
			goto leave;
		}
	}
	else if (c == '*') {
		c = input();
		if (c == '=') {
			r = MULTEQ;
			goto leave;
		} else {
			unput(c);
			r = '*';
			goto leave;
		}
	}
	else if (c == '^') {
		c = input();
		if (c == '=') {
			r = EXPONEQ;
			goto leave;
		} else {
			unput(c);
			r = '^';
			goto leave;
		}
	}
	else if (c == '>') {
		c = input();
		if (c == '=') {
			r = GREQ;
			goto leave;
		} else {
			unput(c);
			r = '>';
			goto leave;
		}
	}
	else if (c == '<') {
		c = input();
		if (c == '=') {
			r = LESSEQ;
			goto leave;
		} else {
			unput(c);
			r = '<';
			goto leave;
		}
	}
	else if (c == '=') {
		c = input();
		if (c == '=') {
			r = CMPEQ;
			goto leave;
		} else {
			unput(c);
			r = '=';
			goto leave;
		}
	}
	else if (c == '!') {
		c = input();
		if (c == '=') {
			r = NOTEQ;
			goto leave;
		} else {
			unput(c);
			r = '!';
			goto leave;
		}
	}
	else if (c == '|') {
		c = input();
		if (c == '|') {
			r = LOGICOR;
			goto leave;
		} else goto error;
	}
	else if (c == '&') {
		c = input();
		if (c == '&') {
			r = LOGICAND;
			goto leave;
		} else goto error;
	}
	else if (c == '(') { r = c; goto leave; }
	else if (c == ')') { r = c; goto leave; }
	else if (c == ';') { r = c; goto leave; }
	else if (c == ',') { r = c; goto leave; }

	else if (c == '{') { r = c; goto leave; }
	else if (c == '}') { r = c; goto leave; }
	else if (c == '[') { r = c; goto leave; }
	else if (c == ']') { r = c; goto leave; }

	else if (c == '?') { r = c; goto leave; }
	else if (c == ':') { r = c; goto leave; }
	else if (c == 0)   { r = 0; goto leave; }
	else goto error;

fileident:
	c = input();

	if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_') goto ident;
	else goto error;

ident:
	c = input();

	if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
		|| c == '_' || (c >= '0' && c <= '9')) goto ident;
	else if (c == '\'') goto channel;
	else {
		unput(c);
		yytext[yylen] = 0;
		r = processident(yytext) ;
		goto leave;
	}

channel:
	c = input();

	if (c >= '1' && c <= '4') {
		yytext[yylen] = 0;
		r = processident(yytext) ;
		goto leave;
	} else goto error;

digits_1:	/* number started with digits */
	c = input();

	if (c >= '0' && c <= '9') goto digits_1;
	else if (c == '.') goto digpoint_1;
	else if (c == 'e' || c == 'E') goto expon_1;
	else {
		unput(c);
		yytext[yylen] = 0;
		r = processconst(yytext);
		goto leave;
	}

digpoint_1: /* dec point and at least 1 digit has been seen */
	c = input();

	if (c >= '0' && c <= '9') goto digpoint_1;
	else if (c == 'e' || c == 'E') goto expon_1;
	else {
		unput(c);
		yytext[yylen] = 0;
		r = processconst(yytext);
		goto leave;
	}

digpoint_2:	/* number started with dec. point */
	c = input();

	if (c >= '0' && c <= '9') goto digpoint_1;
	else goto error;

expon_1:	/* e has been seen, need digits */
	c = input();

	if (c >= '0' && c <= '9') goto expon_3;
	else if (c == '+' || c == '-') goto expon_2;
	else goto error;

expon_2:	/* + or - seen but still need digits */
	c = input();

	if (c >= '0' && c <= '9') goto expon_3;
	else goto error;

expon_3:
	c = input();

	if (c >= '0' && c <= '9') goto expon_3;
	else {
		unput(c);
		yytext[yylen] = 0;
		r = processconst(yytext);
		goto leave;
	}

comment1:	/* comment // to end of line */
	do {
		c = input();
	} while (c != '\n' && c != '\r' && c != 0);
	yylen = 0;
	if (c == 0) { r = 0; goto leave; }
	else goto start;

comment2: { /* C style comments like this one */
		int startline;
		startline = lineno;
		do {
			c = input();
		} while (c != '*' && c != 0);
		if (c == '*') {
			c = input();
			if (c == '/') {
				yylen = 0;
				goto start;
			} else {
				unput(c);	/* may have been another '*' */
				goto comment2;
			}
		} else if (c == 0) {
			dprintf("Open ended /* comment ... started on line %d\n", startline+1);
			yylen = 0;
			r = 0;
			goto leave;
		}
	}

error:

	yytext[yylen] = 0;
	dprintf("illegal input string '%s' on line %d\r", yytext, lineno+1);
	som_cur->x_errorline = lineno+1;
	r = BADTOKEN;
	goto leave;

leave:
	yytext[yylen] = 0;
	return r;
}

static int
processident(char *token) {
	int i;
	Variable *v;

	if (strcmp(token, "if")==0) return IF;
	if (strcmp(token, "else")==0) return ELSE;

	/* is it a func ? */
	for (i=0; i<fnNumFns; ++i) {
		if (strcmp(token, funcs[i].name)==0) break;
	}
	if (i != fnNumFns) {
		if (funclevel >= MAXLEVEL) {
			dprintf("FUNCLEVEL EXCEEDED\r");
			return BADTOKEN;
		}
		funcid[funclevel++] = i;
		return FUNCNAME;
	}

	token[VARNAMELEN-1] = 0;		/* port: names are stored truncated */

	/* is it in var list ? */
	for (i=0; i<numvars; ++i) {
		if (strcmp(token, vars[i].name)==0) break;
	}
	if (varlevel >= MAXLEVEL) {
		dprintf("VARLEVEL EXCEEDED\r");
		return BADTOKEN;
	}
	if (i != numvars) {
		varsid[varlevel++] = i;
		return VARIABLE;
	}

	/* else define it as a var */
	varsid[varlevel++] = numvars;
	v = DefineVar(token);
	if (autodeclare) {
		if (strstr(token, "tbl")) VarSetType(v, sigTable);
		else if (strstr(token, "env"))  VarSetType(v, sigEnvelope);
		else if (strstr(token, "out") || token[0] == '@')  VarSetType(v, sigSample);
		DefaultPField(v);
	}
	return VARIABLE;
}

static int
processconst(char *token) {
	int i;
	float value;

	value = atof(token);
	if (constlevel >= MAXLEVEL) {
		dprintf("CONSTLEVEL EXCEEDED\r");
		return BADTOKEN;
	}
	for (i=0; i<numconsts; ++i) {
		if (constval[i] == value) break;
	}
	if (i != numconsts) {
		constid[constlevel++] = i;
		return CONSTANT;
	}
	if (numconsts >= MAXCONSTS) {
		dprintf("MAXCONSTS EXCEEDED (more than %d different numbers)\r", MAXCONSTS);
		return BADTOKEN;
	}
	constval[numconsts] = value;
	constid[constlevel++] = numconsts++;
	return CONSTANT;
}

void
yyerror(const char *str) {
	int i;
	const char *prev = som_cur->x_prevtext;

	if (strcmp(yytext, "(") == 0 && ((prev[0] >= 'a' && prev[0] <= 'z') || (prev[0] >= 'A' && prev[0] <= 'Z'))) {
		for (i=0; i<fnNumFns; ++i) if (strcmp(prev, funcs[i].name) == 0) break;
		if (i == fnNumFns) {
			dprintf("ERROR on line %d : '%s' is not a unit generator\r", lineno+1, prev);
			if (som_cur->x_errorline == 0) som_cur->x_errorline = lineno+1;
			compileptr = 0;
			return;
		}
	}
	if (yytext[0]) dprintf("ERROR on line %d : %s at '%s'\r", lineno+1, str, yytext);
	else dprintf("ERROR on line %d : %s at the end of the program\r", lineno+1, str);
	if (som_cur->x_errorline == 0) som_cur->x_errorline = lineno+1;
	compileptr = 0;
}
